<?php
namespace App\Http\Controllers\API\Hub\V1;use App\Domain\ApiHub\{ApiIdempotencyService};use App\Domain\ApiHub\Models\TenantApiOperationLink;use App\Domain\Network\Channels\B2C\TenantB2cQuoteService;use Illuminate\Http\Request;use Illuminate\Support\Str;
final class QuoteController extends ApiV1Controller{public function store(Request$r,TenantB2cQuoteService$quotes,ApiIdempotencyService$idem){$key=$this->idempotencyKey($r);if(!$key)return$this->error($r,'IDEMPOTENCY_KEY_REQUIRED','Idempotency-Key es obligatorio.',400);$data=$r->validate(['origin_postal_code'=>['required','regex:/^[0-9]{5}$/'],'destination_postal_code'=>['required','regex:/^[0-9]{5}$/'],'package.type'=>['required','in:sobre,caja'],'package.weight'=>['required','numeric','min:0.01','max:1000'],'package.length'=>['nullable','required_if:package.type,caja','numeric','min:1'],'package.width'=>['nullable','required_if:package.type,caja','numeric','min:1'],'package.height'=>['nullable','required_if:package.type,caja','numeric','min:1'],'external_reference'=>['nullable','string','max:160']]);$tenant=$r->attributes->get('tenant');$client=$r->attributes->get('api_client');$result=$idem->execute($tenant->id,$client->id,'quotes.create',$key,$data,function()use($quotes,$tenant,$client,$data){$quoted=$quotes->quote($tenant,['cp_origen'=>$data['origin_postal_code'],'cp_destino'=>$data['destination_postal_code'],'tipo_envio'=>$data['package']['type'],'peso'=>$data['package']['weight'],'length'=>$data['package']['length']??null,'width'=>$data['package']['width']??null,'height'=>$data['package']['height']??null]);$options=[];foreach($quoted['options']as$o){$id=(string)Str::uuid();$options[$id]=['service_name'=>$o['service'],'service_level'=>$o['delivery']??null,'price'=>(float)$o['price'],'currency'=>'MXN','provider'=>$o['provider'],'service_code'=>$o['service_code']];}$link=TenantApiOperationLink::create(['tenant_id'=>$tenant->id,'api_client_id'=>$client->id,'tenant_operation_id'=>$quoted['operation']->id,'external_reference'=>$data['external_reference']??null,'quote_snapshot'=>['route'=>['origin'=>$data['origin_postal_code'],'destination'=>$data['destination_postal_code']],'package'=>$data['package'],'options'=>$options],'expires_at'=>now()->addMinutes(30)]);return['status'=>201,'body'=>['data'=>['quote_id'=>$link->uuid,'expires_at'=>$link->expires_at->toIso8601String(),'available_services'=>collect($options)->map(fn($o,$id)=>['option_id'=>$id,'service_name'=>$o['service_name'],'service_level'=>$o['service_level'],'estimated_delivery'=>$o['service_level'],'public_price'=>$o['price'],'currency'=>$o['currency']])->values()->all()]]];});return$this->idempotentResponse($r,$result);}}
